// Gmail'den gelen mesajları, gönderene göre gruplanmış Türkçe HTML özete çevirir.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

const mesajlar = $input.all()
  .map((i) => i.json)
  .filter((m) => m && (m.id || m.threadId));

const bugun = new Date().toLocaleDateString('tr-TR', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
});

if (mesajlar.length === 0) {
  return [{
    json: {
      konu: `[n8n] 📬 Günlük özet — yeni e-posta yok (${bugun})`,
      html: '<div style="font-family:sans-serif"><h2>📬 Günlük e-posta özeti</h2><p>Son 24 saatte yeni e-posta yok. 🎉</p></div>',
    },
  }];
}

// Gönderene göre grupla — en çok mail gönderen en üstte.
const gruplar = new Map();
for (const m of mesajlar) {
  const hamKimden = String(m.From || m.from || 'Bilinmeyen gönderen');
  const ad = hamKimden.replace(/<[^>]*>/g, '').replace(/"/g, '').trim() || hamKimden;
  if (!gruplar.has(ad)) gruplar.set(ad, []);
  gruplar.get(ad).push({
    konu: String(m.Subject || m.subject || '(konu yok)'),
    ozet: String(m.snippet || '').slice(0, 160),
  });
}

const bolumler = [...gruplar.entries()]
  .sort((a, b) => b[1].length - a[1].length)
  .map(([ad, liste]) => {
    const satirlar = liste
      .map((k) => `<li style="margin:2px 0"><b>${esc(k.konu)}</b>${k.ozet ? ` — <span style="color:#555">${esc(k.ozet)}</span>` : ''}</li>`)
      .join('');
    return `<h3 style="margin:14px 0 4px">${esc(ad)} <span style="color:#888;font-weight:normal">(${liste.length})</span></h3><ul style="margin:4px 0 10px">${satirlar}</ul>`;
  })
  .join('');

const html = [
  '<div style="font-family:sans-serif;max-width:640px">',
  `<h2 style="margin-bottom:4px">📬 Günlük e-posta özeti — ${bugun}</h2>`,
  `<p>Son 24 saatte <b>${mesajlar.length}</b> e-posta, <b>${gruplar.size}</b> farklı gönderen.</p>`,
  bolumler,
  '<hr style="border:none;border-top:1px solid #eee">',
  '<p style="color:#999;font-size:12px">Bu özet, bilgisayarınızdaki n8n tarafından yerel olarak hazırlandı.</p>',
  '</div>',
].join('');

return [{ json: { konu: `[n8n] 📬 Günlük özet: ${mesajlar.length} e-posta (${bugun})`, html } }];
